export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const NS='http://www.w3.org/2000/svg';export function el(tag,attrs={},text=''){let n=document.createElementNS(NS,tag);for(let[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;return n}
export class Engine{constructor(host,ctx){this.host=host;this.ctx=ctx;this.abort=new AbortController;this.metrics={};this.speed=ctx.speed||1;this.playing=false;this.labels=true}on(e,k,f,o={}){e.addEventListener(k,f,{...o,signal:this.abort.signal})}emit(text){this.ctx.live(text);this.ctx.changed(this.metrics)}setSpeed(v){this.speed=v}setLabels(v){this.labels=v;this.render?.()}pause(){this.playing=!this.playing;clearTimeout(this.timer);if(this.playing)this.run?.();return this.playing}schedule(f,ms){clearTimeout(this.timer);this.timer=setTimeout(()=>{if(this.playing&&!document.hidden)f()},ms/this.speed)}resetView(){}restart(){this.ctx.reload()}destroy(){this.playing=false;clearTimeout(this.timer);cancelAnimationFrame(this.frame);this.abort.abort()}}
